'use strict';
const API = window.STAYHUB_API_BASE || '/api';
// Uploaded photos are served by the API, not by a separately deployed Netlify site.
const photoURL = (url) => /^assets\/uploads\/[0-9a-f]{32}\.(?:jpg|png|webp)$/.test(String(url||'')) ? API + '/media/' + String(url).split('/').pop() : url;
// Never show a browser broken-image glyph when an external photographer URL expires.
// The fallback is a clearly labelled neutral placeholder, not a duplicated hotel photo.
document.addEventListener('error', event => {
 const img=event.target;
 if(img?.tagName==='IMG' && !img.dataset.stayhubFallback && !img.classList.contains('v10-brand-img')){
  img.dataset.stayhubFallback='1';
  img.src='assets/photo-unavailable.svg';
  img.alt='Photo temporarily unavailable';
 }
}, true);


const SESSION_KEY = 'stayhub_public_session';
const $ = (s, root=document) => root.querySelector(s);
const params = new URLSearchParams(location.search);
const page = document.body.dataset.page;
const money = n => 'RM ' + Number(n||0).toLocaleString('en-MY');
const money2 = n => 'RM ' + Number(n||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
const e = value => String(value??'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => new Date().toLocaleDateString('en-CA');
const addDays = n => {const d = new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
let session = null;
try { session = JSON.parse(sessionStorage.getItem(SESSION_KEY)); } catch {_clear();}
function _clear(){sessionStorage.removeItem(SESSION_KEY); session=null;}
function toast(message,error=false){let old=$('.toast');if(old)old.remove();let x=document.createElement('div');x.className='toast'+(error?' error':'');x.setAttribute('role','status');x.textContent=message;document.body.append(x);setTimeout(()=>x.remove(),4500);}
async function req(path,{method='GET',body,auth=false}={}){
  let headers={}; if(body!==undefined)headers['Content-Type']='application/json'; if(auth&&session?.token)headers.Authorization='Bearer '+session.token;
  let response;
  try { response=await fetch(API+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)}); }
  catch {throw new Error('StayHub API is unavailable. Check your Public Netlify deployment and its database/API Functions.');}
  let data=await response.json().catch(()=>({}));
  if(!response.ok){if(response.status===401 && auth){_clear();nav();}throw new Error(data.error||'Request failed.');}
  return data;
}
