function wirePageProgress(){
 const bar=document.createElement('div');bar.className='v6-scroll-progress';bar.setAttribute('aria-hidden','true');document.body.prepend(bar);
 const update=()=>{const max=Math.max(1,document.documentElement.scrollHeight-window.innerHeight);bar.style.transform=`scaleX(${Math.min(1,Math.max(0,scrollY/max))})`;};
 window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update();
}
